--
-- Table structure for table `trans_item`
--

DROP TABLE IF EXISTS `trans_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `trans_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `transaction_id` int unsigned NOT NULL,
  `item_id` int unsigned NOT NULL,
  `rate` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_trans_item_item_id` (`item_id`),
  KEY `fk_trans_item_transaction_id` (`transaction_id`),
  CONSTRAINT `fk_trans_item_item_id` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`),
  CONSTRAINT `fk_trans_item_transaction_id` FOREIGN KEY (`transaction_id`) REFERENCES `transactions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5741686 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;


--
